var factory = new ConnectionFactory() { HostName = "localhost" };
using var connection = factory.CreateConnection();
using var channel = connection.CreateModel();

channel.ExchangeDeclare("task.queue", ExchangeType.Headers, durable: true);
channel.QueueDeclare("us-json-queue", durable: true);
channel.QueueDeclare("high-priority-queue", durable: true);

// Bind: require ALL headers to match (format=json AND region=us)
var allArgs = new Dictionary<string, object>
{
    { "x-match", "all" },
    { "format", "json" },
    { "region", "us" }
};
channel.QueueBind("us-json-queue", "task.queue", "", allArgs);

// Bind: require ANY header to match (format=json OR priority=high)
var anyArgs = new Dictionary<string, object>
{
    { "x-match", "any" },
    { "format", "json" },
    { "priority", "high" }
};
channel.QueueBind("high-priority-queue", "task.queue", "", anyArgs);

const amqp = require('amqplib');

async function publishTask() {
  const conn = await amqp.connect('amqp://localhost');
  const ch = await conn.createChannel();

  await ch.assertExchange('task.queue', 'headers', { durable: true });

  const props = {
    headers: {
      format: 'json',
      region: 'us',
      priority: 'high'
    }
  };

  ch.publish(
    'task.queue',
    '', // routing key is ignored for header exchanges
    props,
    Buffer.from(JSON.stringify({ orderId: 42, total: 99.99 }))
  );

  console.log('Message published with custom headers');
}

publishTask();
